<script setup lang="ts">
import { computed, onMounted, ref } from 'vue'
import { ArrowRight, CheckCircle2, GitBranch, SlidersHorizontal } from 'lucide-vue-next'
import { useRoute, useRouter } from 'vue-router'
import AsyncState from '@/components/shared/AsyncState.vue'
import PageHeader from '@/components/shared/PageHeader.vue'
import { usePlanningConversationStore } from '@/stores/planningConversation'
import { useRoadmapStore } from '@/stores/roadmap'

const route = useRoute(); const router = useRouter(); const roadmap = useRoadmapStore(); const planning = usePlanningConversationStore(); const priority = ref(''); const minutes = ref(180); const adjusting = ref(false)
const draft = computed(() => roadmap.draft); const roots = computed(() => draft.value?.nodes.filter((node) => !node.parentId) ?? []); const children = (parentId: string) => draft.value?.nodes.filter((node) => node.parentId === parentId) ?? []
onMounted(async () => { await roadmap.loadDraft(String(route.params.roadmapId)); if (draft.value?.planningSessionId) await planning.load(draft.value.planningSessionId) })
function nodeStatus(status: string) { return status === 'available' ? '可开始' : status === 'locked' ? '后续开放' : status === 'completed' ? '已完成' : status === 'verified' ? '已验证' : '待确认' }
async function adjust() { if (!planning.session) return; adjusting.value = true; try { const next = await planning.adjust({ weeklyMinutes: minutes.value, priorityDomain: priority.value || undefined }); await roadmap.loadDraft(next.id) } finally { adjusting.value = false } }
async function confirm() { if (!draft.value) return; await roadmap.confirm(draft.value.id, draft.value.revision); await router.push({ name: 'overview' }) }
</script>

<template>
  <div class="page roadmap-preview-page"><AsyncState :loading="roadmap.loading || planning.loading" :error="roadmap.error || planning.error"><template #default><PageHeader eyebrow="02 · Route draft" title="这是一张可以调整的长期路线图。" description="路线图描述能力之间的关系，确认后会从中切出当前可执行的学习计划。" :meta="['3 个能力域', '路线草案', '确认后才切换正式计划']" />
    <template v-if="draft"><section class="draft-summary"><div><small>你的目标</small><h2>{{ draft.goal }}</h2><p>当前草案会优先打开一条能力分支，其余节点保留在长期路线中。</p></div><div class="progress-stat"><strong>{{ draft.progress.total }}</strong><span>个路线节点</span></div></section>
    <section class="adjust-strip"><div><SlidersHorizontal :size="15" aria-hidden="true" /><strong>局部调整</strong><span>只改变草案，不影响已有计划。</span></div><select v-model="priority" aria-label="优先能力域"><option value="">默认：后端系统能力</option><option>后端系统能力</option><option>AI 应用工程</option><option>综合交付能力</option></select><select v-model="minutes" aria-label="每周投入"><option :value="90">每周不足 2 小时</option><option :value="180">每周 2 到 4 小时</option><option :value="300">每周 4 小时以上</option></select><button class="ghost-button" type="button" :disabled="adjusting" @click="adjust">重新生成草案</button></section>
    <section class="roadmap-draft" aria-labelledby="draft-title"><div class="section-label"><GitBranch :size="15" aria-hidden="true" /><span id="draft-title">能力树草案</span></div><div class="domain-grid"><article v-for="root in roots" :key="root.id" class="domain-column"><div class="node-head domain-head"><span class="node-type">能力域</span><h3>{{ root.title }}</h3><p>{{ root.summary }}</p></div><div v-for="capability in children(root.id)" :key="capability.id" class="capability-row"><div><span class="node-type">能力分支</span><strong>{{ capability.title }}</strong><p>{{ capability.summary }}</p></div><span class="status-chip" :class="capability.status"><CheckCircle2 :size="12" aria-hidden="true" />{{ nodeStatus(capability.status) }}</span><div class="leaf-list"><div v-for="leaf in children(capability.id)" :key="leaf.id"><span>{{ leaf.title }}</span><small>{{ leaf.learningMode === 'lab' ? '真实实践' : '知识确认' }} · {{ leaf.estimatedMinutes }} 分钟</small></div></div></div></article></div></section>
    <section class="confirm-bar"><div><strong>确认这张路线图</strong><span>确认后会归档旧路线，并保留历史实践与文章。</span></div><button class="primary-button" type="button" @click="confirm">确认并进入总览 <ArrowRight :size="14" aria-hidden="true" /></button></section></template>
  </template></AsyncState></div>
</template>

<style scoped>
.roadmap-preview-page { max-width: 1120px; }.draft-summary { display: flex; align-items: end; justify-content: space-between; gap: 22px; margin-top: 28px; padding: 19px 0; border-top: 2px solid var(--orange); border-bottom: 1px solid var(--line); }.draft-summary small, .progress-stat span { color: #7e8781; font: 9px var(--mono); }.draft-summary h2 { margin: 7px 0 0; color: var(--ink); font: 400 23px var(--serif); }.draft-summary p { margin: 7px 0 0; color: var(--muted); font-size: 11px; }.progress-stat { display: flex; align-items: baseline; gap: 7px; flex: 0 0 auto; }.progress-stat strong { color: var(--orange); font: 400 36px var(--serif); }.adjust-strip { display: flex; align-items: center; flex-wrap: wrap; gap: 9px; margin-top: 20px; padding: 11px 0; border-bottom: 1px solid var(--line); }.adjust-strip > div { display: inline-flex; align-items: center; gap: 7px; margin-right: auto; color: var(--blue); }.adjust-strip > div span { color: var(--muted); font-size: 10px; }.adjust-strip select { min-height: 32px; border: 1px solid var(--line); background: var(--paper); color: #52605a; font-size: 10px; }.roadmap-draft { margin-top: 28px; }.section-label { display: flex; align-items: center; gap: 7px; color: var(--blue); font: 9px var(--mono); text-transform: uppercase; }.domain-grid { display: grid; grid-template-columns: repeat(3, 1fr); gap: 18px; margin-top: 14px; }.domain-column { min-width: 0; border-top: 2px solid var(--blue); }.domain-column:nth-child(2) { border-top-color: var(--orange); }.domain-column:nth-child(3) { border-top-color: var(--green); }.domain-head { padding: 13px 0 15px; border-bottom: 1px solid var(--line); }.node-type { display: block; color: #89908b; font: 8px var(--mono); text-transform: uppercase; }.domain-head h3 { margin: 7px 0 0; color: var(--ink); font: 400 20px var(--serif); }.domain-head p, .capability-row p { margin: 6px 0 0; color: var(--muted); font-size: 10px; line-height: 1.5; }.capability-row { padding: 14px 0; border-bottom: 1px solid var(--line); }.capability-row strong { display: block; margin-top: 5px; color: #45534c; font-size: 12px; font-weight: 500; }.status-chip { display: inline-flex; align-items: center; gap: 4px; margin-top: 9px; color: #8a918b; font: 9px var(--mono); }.status-chip.available { color: var(--green); }.leaf-list { display: grid; gap: 7px; margin-top: 12px; padding-left: 12px; border-left: 1px solid var(--line); }.leaf-list div { display: flex; justify-content: space-between; gap: 8px; }.leaf-list span { color: #5f6c65; font-size: 10px; }.leaf-list small { color: #959b96; font: 8px var(--mono); text-align: right; }.confirm-bar { display: flex; align-items: center; justify-content: space-between; gap: 20px; margin-top: 27px; padding: 15px 0; border-top: 2px solid var(--orange); }.confirm-bar strong { display: block; color: var(--ink); font: 400 17px var(--serif); }.confirm-bar span { display: block; margin-top: 5px; color: var(--muted); font-size: 10px; }.primary-button, .ghost-button { display: inline-flex; align-items: center; gap: 6px; min-height: 34px; padding: 8px 11px; border: 1px solid #b66844; background: var(--orange-soft); color: #995436; font-size: 10px; cursor: pointer; }.ghost-button { border-color: var(--line); background: var(--paper); color: var(--blue); }.primary-button:disabled, .ghost-button:disabled { opacity: .55; cursor: wait; }
@media (max-width: 820px) { .domain-grid { grid-template-columns: 1fr; gap: 24px; }.draft-summary, .confirm-bar { align-items: stretch; flex-direction: column; }.confirm-bar button { justify-content: center; } }
</style>
